    questions: [
      { kind: 'choice', q: 'Que jouait Théo quand Ioana a senti la première contraction ?', options: ['Une berceuse', 'La valse d’Henri', 'La Vie en rose'], answer: 'La valse d’Henri' },
      { kind: 'choice', q: 'Qui a appelé le taxi ?', options: ['Julien', 'Radu', 'Madame Bernard'], answer: 'Radu' },
      { kind: 'choice', q: 'Où était la grand-mère quand le bébé est né ?', options: ['À Iași', 'Dans le car pour Lyon', 'À la maternité'], answer: 'Dans le car pour Lyon' },
      { kind: 'fill', before: 'Je suis si heureuse que tu', after: 'là. (être)', answers: ['sois'] },
    ],
